import Foundation
@testable import FieldLogStorage

private struct Fixture: Decodable {
  let port: UInt16
  let workspace: UUID
  let project: UUID
  let otherProject: UUID
  let firstToken: String
  let secondToken: String
  let firstOperation: String
  let action: String
  let releaseFirst: Bool
  let expectedFirst: String
  let expectedSecond: String
  let expectedStore: String
  let legacy: Bool
}

@MainActor private final class Slot {
  let ownership = LocalWorkspaceSignIn.RequestOwnership()
  var bytes: Data?
}

@MainActor private struct Adapter: LocalWorkspaceSignIn.CredentialStore {
  let slot: Slot
  var requestOwnership: LocalWorkspaceSignIn.RequestOwnership { slot.ownership }
  func read() throws -> LocalWorkspaceSignIn.Credential? {
    try slot.bytes.map { try JSONDecoder().decode(LocalWorkspaceSignIn.Credential.self, from: $0) }
  }
  func save(_ entry: LocalWorkspaceSignIn.Credential) throws {
    slot.bytes = try JSONEncoder().encode(entry)
  }
  func clear() throws { slot.bytes = nil }
}

private struct Check: Error { let message: String }

@main @MainActor private struct Run {
  static func main() async {
    do {
      try await probe()
    } catch {
      FileHandle.standardError.write(Data("Independent fixture failed: \(error)\n".utf8))
      exit(1)
    }
  }

  static func require(_ condition: Bool, _ message: String) throws {
    guard condition else { throw Check(message: message) }
  }

  static func probe() async throws {
    let f = try JSONDecoder().decode(Fixture.self, from: Data((readLine() ?? "").utf8))
    let directory = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
    let slot = Slot()
    let scope = LocalWorkspaceSignIn.Scope(port: f.port, workspaceID: f.workspace, projectID: f.project)
    let unrelated = LocalWorkspaceSignIn.Scope(
      port: f.port, workspaceID: f.workspace, projectID: f.otherProject)
    let account = "fixture-review"
    let control = LocalWorkspaceSignIn(scope: scope, store: Adapter(slot: slot))
    let firstService = LocalWorkspaceSignIn(scope: scope, store: Adapter(slot: slot))
    let secondService = LocalWorkspaceSignIn(scope: scope, store: Adapter(slot: slot))
    _ = try await control.signIn(accountID: account, token: f.firstToken)
    if f.legacy, let bytes = slot.bytes {
      var legacy = try JSONSerialization.jsonObject(with: bytes) as? [String: Any] ?? [:]
      try require(legacy.removeValue(forKey: "admissionID") != nil, "seed has an admission ID")
      slot.bytes = try JSONSerialization.data(withJSONObject: legacy)
    }
    if f.action == "empty-signout" { try control.signOut() }
    let seed = slot.bytes
    let first = Task { () throws -> LocalWorkspaceSignIn.Admission? in
      if f.firstOperation == "restore" { return try await firstService.restore() }
      return try await firstService.signIn(accountID: account, token: f.firstToken)
    }
    try await arrived("first", in: directory)

    var secondResult = "none"
    var replacement: Data?
    let firstResult: String
    switch f.action {
    case "signout", "empty-signout":
      try control.signOut()
      try require(slot.bytes == nil, "sign-out left bytes")
      try release("first", in: directory)
      firstResult = await observe(first, scope: scope)
    case "unrelated-restore":
      let service = LocalWorkspaceSignIn(scope: unrelated, store: Adapter(slot: slot))
      let result = try await service.restore()
      try require(result == nil && slot.bytes == seed, "unrelated restore altered the slot")
      try release("first", in: directory)
      firstResult = await observe(first, scope: scope)
    default:
      let second = Task { () throws -> LocalWorkspaceSignIn.Admission? in
        if f.action == "restore" { return try await secondService.restore() }
        return try await secondService.signIn(accountID: account, token: f.secondToken)
      }
      try await arrived("second", in: directory)
      if f.releaseFirst {
        try release("first", in: directory)
        firstResult = await observe(first, scope: scope)
        try require(slot.bytes == seed, "superseded request changed the slot while newest was pending")
        try release("second", in: directory)
        secondResult = await observe(second, scope: scope)
        replacement = slot.bytes
      } else {
        try release("second", in: directory)
        secondResult = await observe(second, scope: scope)
        replacement = slot.bytes
        try release("first", in: directory)
        firstResult = await observe(first, scope: scope)
        try require(slot.bytes == replacement, "superseded request changed the completed outcome")
      }
    }

    try require(firstResult == f.expectedFirst, "older result \(firstResult) expected \(f.expectedFirst)")
    try require(secondResult == f.expectedSecond, "newer result \(secondResult) expected \(f.expectedSecond)")
    switch f.expectedStore {
    case "clear":
      try require(slot.bytes == nil, "expected empty slot")
    case "seed":
      try require(slot.bytes == seed && seed != nil, "expected byte-identical original")
    case "replacement":
      let saved = try Adapter(slot: slot).read()
      try require(slot.bytes == replacement && slot.bytes != seed && saved?.admissionID != nil
        && saved?.token == f.secondToken && saved?.accountID == account && saved?.scope == scope,
        "expected fresh matching admission")
    default:
      throw Check(message: "unknown expected store")
    }
    print("\(firstResult)/\(secondResult)/\(f.expectedStore)")
  }

  static func observe(_ task: Task<LocalWorkspaceSignIn.Admission?, Error>,
    scope: LocalWorkspaceSignIn.Scope) async -> String
  {
    switch await task.result {
    case .success(nil): return "empty"
    case .success(.some(let admission)):
      guard admission.accountID == "fixture-review", admission.scope == scope else { return "wrong-admission" }
      return admission.offline ? "offline" : "online"
    case .failure(is CancellationError): return "superseded"
    case .failure(LocalWorkspaceSignIn.Failure.rejected): return "denied"
    case .failure(LocalWorkspaceSignIn.Failure.serviceUnavailable): return "unavailable"
    default: return "unexpected"
    }
  }

  static func arrived(_ name: String, in directory: URL) async throws {
    let path = directory.appendingPathComponent("\(name)-arrived").path
    let deadline = ContinuousClock.now + .seconds(2)
    while !FileManager.default.fileExists(atPath: path) {
      try require(ContinuousClock.now < deadline, "\(name) did not arrive")
      try await Task.sleep(for: .milliseconds(5))
    }
  }

  static func release(_ name: String, in directory: URL) throws {
    try Data().write(to: directory.appendingPathComponent("\(name)-release"), options: .atomic)
  }
}
